repo.trades.py:
"""Trade records."""


class Trade:
    def __init__(self, desk, volume):
        self.desk = desk
        self.volume = volume

    def __repr__(self):
        return "Trade(%r, %r)" % (self.desk, self.volume)


ROWS = [('metals', 4), ('energy', 3), ('fx', 40), ('fx', 31), ('bonds', 15)]


def load_trades():
    """Yield the stored trades one at a time."""
    for desk, volume in ROWS:
        yield Trade(desk, volume)

repo.registry.py:
"""Registry of trades by desk."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered trade."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(trade):
    """Add one trade to the registry."""
    _ALL.append(trade)


def find(desk):
    """Return the trades registered under this desk."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.desk, []).append(x)
    return _BY_KEY.get(desk, [])

